stages.code:
# 1. SEPARATION — avoid crowding
func _separate(neighbors: Array) -> Vector3:
	var steer = Vector3.ZERO
	for n in neighbors:
		var diff = position - n.position
		var d = diff.length()
		if d > 0.0 and d < separation_radius:
			steer += diff.normalized() / d  # inverse-square-ish push
	return steer.normalized() * separation_weight

# 2. ALIGNMENT — match neighbor heading
func _align(neighbors: Array) -> Vector3:
	var avg_vel = Vector3.ZERO
	for n in neighbors:
		avg_vel += n.velocity
	if neighbors.size() > 0:
		avg_vel /= neighbors.size()
	return (avg_vel - velocity).normalized() * alignment_weight

# 3. COHESION — steer toward neighbor center
func _cohere(neighbors: Array) -> Vector3:
	var center = Vector3.ZERO
	for n in neighbors:
		center += n.position
	if neighbors.size() > 0:
		center /= neighbors.size()
	return (center - position).normalized() * cohesion_weight

class Boid:
	var position: Vector3
	var velocity: Vector3
	var acceleration: Vector3
	var perception_radius: float = 2.0

	func find_neighbors(all_boids: Array) -> Array:
		var result = []
		for other in all_boids:
			if other == self: continue
			if position.distance_to(other.position) < perception_radius:
				result.append(other)
		return result

	func update(all_boids: Array, delta: float) -> void:
		var neighbors = find_neighbors(all_boids)
		acceleration = _separate(neighbors) + _align(neighbors) + _cohere(neighbors)
		velocity += acceleration * delta
		velocity = velocity.limit_length(max_speed)
		position += velocity * delta

extends Node3D
class_name BoidManager

@export var boid_scene: PackedScene
@export var num_boids = 50
@export var spawn_area_size = Vector3(20, 10, 20)

var _boids: Array[Node3D] = []

func _ready() -> void:
	for i in num_boids:
		var b = boid_scene.instantiate()
		b.position = Vector3(
			randf_range(-spawn_area_size.x / 2, spawn_area_size.x / 2),
			randf_range(-spawn_area_size.y / 2, spawn_area_size.y / 2),
			randf_range(-spawn_area_size.z / 2, spawn_area_size.z / 2)
		)
		b.velocity = Vector3(randf_range(-1, 1), randf_range(-1, 1), randf_range(-1, 1))
		add_child(b)
		_boids.append(b)

func _process(delta: float) -> void:
	for b in _boids:
		b.update(_boids, delta)

@export var left_controller_path: NodePath
@export var right_controller_path: NodePath
@export var interaction_radius = 3.0

func _apply_vr_interaction(b: Boid) -> void:
	var left = get_node_or_null(left_controller_path)
	var right = get_node_or_null(right_controller_path)

	if left and left.is_button_pressed("trigger_click"):
		var d = b.position.distance_to(left.global_position)
		if d < interaction_radius:
			# Attract
			b.acceleration += (left.global_position - b.position).normalized() * 5.0

	if right and right.is_button_pressed("trigger_click"):
		var d = b.position.distance_to(right.global_position)
		if d < interaction_radius:
			# Repel
			b.acceleration += (b.position - right.global_position).normalized() * 5.0
